def enc(a,dtype):return base64.b64encode(gzip.compress(np.asarray(a,dtype=dtype).tobytes())).decode()
def mesh(v,f):return dict(v=enc(v,'<f4'),f=enc(f,'<u4'))
def package(n):
 vv=np.concatenate([n['v'],n['fin_v'],n['teeth_v']]);return dict(bounds=np.r_[vv.min(0),vv.max(0)].tolist(),meshes={role:mesh(n[vk],n[fk])for role,vk,fk in [('part','v','f'),('fin','fin_v','fin_f'),('teeth','teeth_v','teeth_f')]})
new=package(np.load(src/'parts/X062.npz'));old=package(np.load(OLD/'parts/X062.npz'));groups=np.load(src/'verification/fin_groups.npz');new['groups']={r['id']:dict(mesh=mesh(groups[f'g{i}_v'],groups[f'g{i}_f']),**r)for i,r in enumerate(g['fin_bodies'],1)}
